const PROFILE=[[-710,57.70],[-670,57.85],[-610,58.11],[-520,58.18],[-460,58.10],[-400,58.10],[-340,58.05],[-310,57.70],[-235,57.76],[-160,57.375],[-115,57.20],[-55,57.166],[5,56.789],[65,56.595],[110,56.094],[155,55.294],[200,54.184],[245,52.831],[286,51.60]];
function interpolate(points,x,index=1){let i=points.findIndex(p=>p[0]>x)-1;if(i<0)i=x<points[0][0]?0:points.length-2;i=Math.min(points.length-2,i);const [a,b]=[points[i],points[i+1]];return a[index]+(b[index]-a[index])*Math.max(0,Math.min(1,(x-a[0])/(b[0]-a[0])));}
const top=x=>interpolate(PROFILE,x)-WATER_NAP;
function limits(x){const ys=[];for(const ring of DECK_RINGS)for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];if(Math.min(a[0],b[0])<=x&&x<Math.max(a[0],b[0]))ys.push(a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0]));}if(!ys.length)return x<0?limits(-709.7):limits(285.5);return [Math.min(...ys),Math.max(...ys)];}
// De twee rivierpijlers staan in BGT op -52,3 en +69,7 m, hoofdveld 122 m.
const RIVER_PIERS=[-52.3,69.7];
function depth(x){return x<-125||x>130?2.1:2.4+3.5*Math.max(0,1-Math.min(...RIVER_PIERS.map(p=>Math.abs(x-p)))/61)**2;}
function loftX(stations,sectionAt){const verts=[],tris=[],n=sectionAt(stations[0]).length;for(const x of stations)for(const [y,z]of sectionAt(x))verts.push(x,y,z);for(let i=0;i<stations.length-1;i++)for(let j=0;j<n;j++){const a=i*n+j,b=i*n+(j+1)%n,c=(i+1)*n+(j+1)%n,d=(i+1)*n+j;tris.push(a,b,c,a,c,d);}for(let j=1;j<n-1;j++){tris.push(0,j+1,j);const k=(stations.length-1)*n;tris.push(k,k+j,k+j+1);}return new Manifold(new Mesh({numProp:3,vertProperties:Float32Array.from(verts),triVerts:Uint32Array.from(tris)}));}
const stations=[...new Set([...Array.from({length:500},(_,i)=>-710+i*996/499),...PROFILE.map(p=>p[0]),...DECK_RINGS.flatMap(r=>r.flatMap(p=>[p[0]-.001,p[0],p[0]+.001])),-125.01,-125,130,130.01])].sort((a,b)=>a-b);
const footprint=CrossSection.union(DECK_RINGS.map(section));
const deck=footprint.extrude(SLAB).translate([0,0,-SLAB]).refineToLength(3).warp(v=>{v[2]+=top(v[0]);});
const mask=footprint.extrude(40);
const kokers=[0,1].map(side=>loftX(stations,x=>{const [lo,hi]=limits(x),c=(lo+hi)/2;const a=side?c+.5:lo+1.4,b=side?hi-1.4:c-.5;return [[a+.65,top(x)-depth(x)],[b-.65,top(x)-depth(x)],[b,top(x)-SLAB+.1],[a,top(x)-SLAB+.1]];}).intersect(mask));
const piers=BGT_SUPPORTS.map(({ring})=>{const x=ring.reduce((s,p)=>s+p[0]/ring.length,0);return prism(ring,0,Math.max(.1,top(x)-depth(x)+.2)).intersect(mask);}).filter(s=>!s.isEmpty());
